package com.example.macollection.data

/** Une console du catalogue intégré (preset). */
data class ConsolePreset(
    val brand: String,
    val name: String,
    val year: Int,
    val kind: String,        // "Salon" ou "Portable"
    val cpu: String,
    val memory: String,
    val description: String
) {
    /** Texte de fiche prêt à stocker dans l'objet de la collection. */
    fun specsText(): String = buildString {
        append("$brand $name ($year) — $kind\n")
        append("CPU : $cpu\n")
        append("Mémoire : $memory")
        if (description.isNotBlank()) append("\n$description")
    }
}

